@10 n="covalent_bond_direction_anisotropy" d="Rotationally invariant covalent-bond direction anisotropy: one minus three times the smallest normalized tensor eigenvalue." B=2054
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(len(row) != 3 for row in matrix):
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    coords = [t.get('frac_coords') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    xx = 0.0
    yy = 0.0
    zz = 0.0
    xy = 0.0
    xz = 0.0
    yz = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if not (0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6):
            continue
        a = radii[i]
        b = radii[j]
        if a is None or b is None or a <= 0 or b <= 0 or d > 1.25 * (a + b):
            continue
        u = coords[i]
        v = coords[j]
        image = edge.get('image')
        if u is None or v is None or image is None:
            continue
        if len(u) != 3 or len(v) != 3 or len(image) != 3:
            continue
        f0 = v[0] + image[0] - u[0]
        f1 = v[1] + image[1] - u[1]
        f2 = v[2] + image[2] - u[2]
        x = f0 * matrix[0][0] + f1 * matrix[1][0] + f2 * matrix[2][0]
        y = f0 * matrix[0][1] + f1 * matrix[1][1] + f2 * matrix[2][1]
        z = f0 * matrix[0][2] + f1 * matrix[1][2] + f2 * matrix[2][2]
        norm2 = x * x + y * y + z * z
        if norm2 <= 0:
            continue
        w = occ[i] * occ[j] / norm2
        xx += w * x * x
        yy += w * y * y
        zz += w * z * z
        xy += w * x * y
        xz += w * x * z
        yz += w * y * z
    trace = xx + yy + zz
    if trace <= 0:
        return 0.0
    eigenvalues = np.linalg.eigvalsh(np.array([[xx, xy, xz], [xy, yy, yz], [xz, yz, zz]]))
    return float(max(0.0, min(1.0, 1.0 - 3.0 * eigenvalues[0] / trace)))
@end
@11 n="nominal_main_group_electron_demand" d="Signed nominal main-group electron demand per occupied atom; groups 15-17 accept, groups 1, 2 and 13 donate." B=629
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    demand = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        group = (props.get(site.get('element')) or {}).get('group')
        if group is None:
            continue
        if 15 <= group <= 17:
            demand += o * (18.0 - group)
        elif group == 1 or group == 2:
            demand -= o * group
        elif group == 13:
            demand -= 3.0 * o
    return demand / total if total > 0 else 0.0
@end
